  "{id} 승인 요청을 만들었습니다 — 웹 화면의 승인함에서 사람이 승인해야 적용됩니다": "Approval requested for {id} — a person must approve it in the web inbox before it applies",
  "{id} 은(는) 이미 그 상태입니다": "{id} is already in that state",
