  "lease 놓기": "Release lease",
  "lease 는 FarShell 이 직접 하는 쓰기(커밋·업로드 등)만 막습니다. 셸이나 편집기에서 직접 쓰는 것은 막지 못하는 권고 장치입니다.": "A lease only blocks writes FarShell makes itself (commits, uploads and so on). It is an advisory marker: writes made directly from a shell or editor are not blocked.",
  "lease 는 누가 어느 폴더를 쓰는지 알리는 권고 장치입니다. 지금은 막지 않고, 켜도 FarShell 자신의 쓰기 밖(셸·편집기)에서는 막지 못합니다.": "A lease tells who is using which folder. It does not block anything right now, and even when enforcement is on it cannot stop writes made outside FarShell itself (shell, editor).",
