  "위임 하위": "delegated child",
  "이 lease 를 놓습니다. 상속된 하위 lease 도 함께 놓이고, 에이전트는 다시 잡아야 합니다. 계속할까요?": "This releases the lease. Inherited child leases are released with it, and the agent has to take it again. Continue?",
  "이 권한을 회수하면 이 페어 전체가 끝납니다. 두 쪽이 받은 권한과 폴더 lease 가 모두 거두어집니다. 계속할까요?": "Revoking this permission ends the whole pair. The permissions and folder leases both sides received are all withdrawn. Continue?",
  "이 기능은 서버에서 켜야 합니다 — 서버 설정 {env} 에 {tok} 를 더합니다.": "This feature must be turned on in the server: add {tok} to the server setting {env}.",
  "이 페어를 끝냅니다. 두 쪽이 받은 권한과 폴더 lease 가 모두 거두어집니다. 계속할까요?": "This ends the pair. The permissions and folder leases both sides received are all withdrawn. Continue?",
  "이 페어를 회수합니다. 두 에이전트가 받은 권한과 폴더 lease 가 모두 거두어집니다. 계속할까요?": "This revokes the pair. The permissions and folder leases both agents received are all withdrawn. Continue?",
  "읽기": "Read",
  "잡혀 있는 폴더 lease 가 없습니다. 에이전트가 폴더를 쓰기 시작하면 여기에 나타납니다.": "No folder lease is held. Leases show up here when an agent starts using a folder.",
  "정리 상태를 확인하지 못했습니다": "Could not check the cleanup state",
  "정리 중 — 남은 권한 {g}개 · lease {l}개": "Cleaning up - permissions left {g}, leases left {l}",
  "정말 모든 에이전트 권한을 회수할까요? 공유 세션·메시지·다른 맥·위임·페어·일반 권한이 전부 거두어지고, 에이전트는 다시 승인을 받아야 합니다. 비밀번호를 다시 확인합니다.": "Really revoke all agent permissions? Shared sessions, messages, other Macs, delegations, pairs and general permissions are all withdrawn and agents have to ask for approval again. You will be asked for your password again.",
