  "모든 에이전트의 권한을 한 번에 회수하고 대기 중인 요청을 비웁니다. 사람의 로그인과 기본 권한은 그대로입니다.": "Revokes every agent permission at once and clears pending requests. Your login and your own permissions are untouched.",
