  "코드가 정해 둔 기본 권한입니다. 읽기 전용이라 회수할 수 없고, 아래 목록에 없는 권한은 모두 승인이 필요합니다.": "These are the built-in defaults set in code. They are read-only and cannot be revoked; anything not listed needs an approval.",
