  "lease 가 끝나길 기다리거나 보유자와 정리하세요. 이 guard 는 알리는 장치입니다 — git commit --no-verify 로 건너뛸 수 있습니다.": "Wait for the lease to end or sort it out with the holder. This guard only informs — git commit --no-verify skips it.",
  "lease 가 없습니다": "No leases",
  "lease 는 권고입니다 — 서버가 안 닿으면 경고만 하고 커밋은 통과합니다. 같은 계정의 셸은 --no-verify 로 건너뛸 수 있습니다.": "Leases are advisory — if the server is unreachable this only warns and the commit goes through. A shell of the same account can skip it with --no-verify.",
  "lease 는 열람 루트(VT_BROWSE_ROOTS) 안, 거부 목록·숨김 상태 폴더 밖의 경로에만 걸 수 있습니다: {why}": "A lease can only cover paths inside the browse roots (VT_BROWSE_ROOTS) and outside denied or hidden-state folders: {why}",
