  "pair 의 driver 가 정확히 한 명이 아닙니다": "The pair does not have exactly one driver",
  "raw 키 입력(세션에 키를 그대로 보냄)": "Raw key input (keys are sent to the session as they are)",
  "role 은 driver 또는 navigator 입니다": "role must be driver or navigator",
  "sessions·dirs·elevated 는 목록이어야 합니다": "sessions, dirs and elevated must be lists",
  "그런 pair 가 없습니다": "No such pair",
  "그런 세션이 없습니다": "No such session",
  "꺼져 있는데 저장된 pair {n}개가 남아 있습니다 — 권한은 효력이 없습니다": "The feature is off but {n} stored pair(s) remain - their permissions have no effect",
  "꺼짐 (VT_AUTHZ_ENFORCE 에 pair 를 더하면 켜짐)": "Off (add pair to VT_AUTHZ_ENFORCE to turn it on)",
