  "  ⓘ 다음 'fsh update' 는 채널({ch}) 기준으로 다시 올라갑니다. 고정하려면 devmode 로 바꾸세요.": "  ⓘ The next 'fsh update' moves up again by channel ({ch}). Switch to devmode to stay here.",
  "  ⓘ 되돌리기: fsh update --rollback": "  ⓘ To undo: fsh update --rollback",
  "  ⓘ 서버가 떠 있다면 'fsh restart' 로 반영하세요 (자동으로 재시작하지 않습니다).": "  ⓘ If the server is running, apply it with 'fsh restart' (it is not restarted automatically).",
  "  ⓘ 이 지문이 릴리스에 서명하는 본인 키의 지문(ssh-keygen -lf <키>.pub)과 같은지 확인하세요.": "  ⓘ Check that this fingerprint matches your own release-signing key (ssh-keygen -lf <key>.pub).",
  "  ⚠ fsh 스킬: 다른 곳을 가리키는 링크입니다 ({dst}) — 건드리지 않았습니다": "  ⚠ fsh skill: the link points elsewhere ({dst}) — left untouched",
  "  ⚠ fsh 스킬: 링크가 아닌 사본입니다 — 덮어쓰지 않았습니다. 최신화: rm -r {dst} && fsh sync": "  ⚠ fsh skill: this is a copy, not a link — not overwritten. To refresh: rm -r {dst} && fsh sync",
